type ShoppingCart struct {
    items map[string]float64  // item name -> price * quantity
    discountPercent float64
}

func NewCart() *ShoppingCart {
    return &ShoppingCart{items: make(map[string]float64)}
}

func (c *ShoppingCart) AddItem(name string, price float64, qty int) {
    c.items[name] += price * float64(qty)
}

func (c *ShoppingCart) RemoveItem(name string) {
    delete(c.items, name)
}

func (c *ShoppingCart) Total() float64 {
    sum := 0.0
    for _, price := range c.items {
        sum += price
    }
    return sum * (1 - c.discountPercent)
}

func (c *ShoppingCart) ApplyDiscount(percent float64) {
    c.discountPercent = percent / 100
}
